function debounce(fn, wait) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      fn.apply(this, args);
    }, wait);
  };
}

// usage
const onResize = debounce(() => console.log('resized'), 300);
window.addEventListener('resize', onResize);

