function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function retry(fn, { retries = 3, baseDelay = 200, factor = 2, jitter = true } = {}) {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (err) {
      attempt += 1;
      if (attempt > retries) throw err;
      let wait = baseDelay * factor ** (attempt - 1);
      if (jitter) wait = Math.random() * wait;
      await delay(wait);
    }
  }
}

// usage
retry(() => fetch('/api/data').then(r => r.json()), { retries: 4 });

